package com.example.ui

object StringsRes {
    fun get(key: String, lang: String): String {
        val isHindi = lang == "hi"
        return when (key) {
            "app_title" -> if (isHindi) "ऐडस्किप प्रो" else "AdSkip Pro"
            "app_subtitle" -> if (isHindi) "ऑटो विज्ञापन स्किप और शील्ड" else "Auto Ad Skipper & Shield"
            "status_active" -> if (isHindi) "सुरक्षा सक्रिय है" else "Shield Active & Protecting"
            "status_inactive" -> if (isHindi) "सेवा बंद है - चालू करें" else "Service Inactive - Tap to Enable"
            "status_desc_active" -> if (isHindi) "सभी ऐप्स में विज्ञापन स्वतः स्किप हो रहे हैं" else "Auto-skipping ads across video players & apps"
            "status_desc_inactive" -> if (isHindi) "ऐड्स को अपने आप स्किप करने के लिए Accessibility अनुमति दें" else "Enable Accessibility permission to auto-skip ads"
            "btn_enable" -> if (isHindi) "सेटिंग्स में ऑन करें" else "Enable in Settings"
            "total_skipped" -> if (isHindi) "कुल स्किप किए गए" else "Total Ads Skipped"
            "time_saved" -> if (isHindi) "बचाया गया समय" else "Time Saved"
            "today_skipped" -> if (isHindi) "आज के विज्ञापन" else "Today's Skips"
            "sec" -> if (isHindi) "सेकंड" else "sec"
            "min" -> if (isHindi) "मिनट" else "min"
            "hrs" -> if (isHindi) "घंटे" else "hrs"
            "controls_title" -> if (isHindi) "सुरक्षा सेटिंग्स" else "Protection Controls"
            "master_switch" -> if (isHindi) "मास्टर ऑटो-स्किप" else "Master Auto-Skip"
            "master_switch_desc" -> if (isHindi) "सभी ऐप्स पर 'Skip Ad' बटन स्वतः दबाएं" else "Automatically click 'Skip Ad' on all apps"
            "auto_mute" -> if (isHindi) "विज्ञापन की आवाज़ म्यूट करें" else "Mute Video Ads Audio"
            "auto_mute_desc" -> if (isHindi) "अनस्किपेबल वीडियो विज्ञापन के दौरान आवाज़ बंद रखें" else "Automatically mute media volume during video ads"
            "turbo_mode" -> if (isHindi) "टर्बो मोड (0ms फ़ास्ट)" else "Turbo Mode (0ms Instant)"
            "turbo_mode_desc" -> if (isHindi) "बटन दिखते ही तुरंत क्लिक करें" else "Click skip button immediately without delay"
            "app_filters_title" -> if (isHindi) "सपोर्टेड ऐप्स" else "Protected Apps"
            "filter_youtube" -> if (isHindi) "यूट्यूब वीडियो ऐड्स" else "YouTube Video Ads"
            "filter_browsers" -> if (isHindi) "ब्राउज़र एवं वेब ऐड्स" else "Web & Browser Ads"
            "filter_games" -> if (isHindi) "गेम्स एवं अन्य ऐप्स" else "Mobile Games & Popups"
            "simulator_title" -> if (isHindi) "लाइव टेस्ट सिम्युलेटर" else "Live Ad Test Simulator"
            "simulator_desc" -> if (isHindi) "जांचें कि ऑटो-स्किप कैसे काम करता है" else "Verify auto-skip working in real-time"
            "btn_test_sim" -> if (isHindi) "टेस्ट ऐड चलाएं" else "Run Test Ad Simulation"
            "sim_status_ad_playing" -> if (isHindi) "विज्ञापन चल रहा है... स्किप बटन का इंतज़ार" else "Ad Playing... waiting for Skip button"
            "sim_status_skippable" -> if (isHindi) "स्किप बटन सक्रिय! ऑटो-क्लिक हो रहा है..." else "Skip button visible! Auto-clicking..."
            "sim_status_skipped" -> if (isHindi) "विज्ञापन सफलतापूर्वक स्किप हुआ!" else "Ad Successfully Skipped!"
            "btn_skip_ad" -> if (isHindi) "विज्ञापन छोड़ें" else "Skip Ad"
            "dns_shield_title" -> if (isHindi) "सिस्टम-वाइड बैनर ब्लॉकर (DNS)" else "System-Wide DNS Shield"
            "dns_shield_desc" -> if (isHindi) "वेबसाइट्स और ऐप्स में बैनर विज्ञापनों को रोकने के लिए Android Private DNS सेट करें" else "Block app banners and trackers via Android Private DNS"
            "btn_open_dns" -> if (isHindi) "Private DNS सेटिंग्स खोलें" else "Open DNS Settings"
            "history_title" -> if (isHindi) "हाल ही में स्किप किए गए विज्ञापन" else "Recent Skipped Ads"
            "btn_clear_history" -> if (isHindi) "इतिहास साफ़ करें" else "Clear Log"
            "guide_title" -> if (isHindi) "ऐडस्किपर को कैसे चालू करें?" else "How to enable AdSkip Pro?"
            "guide_step_1" -> if (isHindi) "1. 'सेटिंग्स में ऑन करें' बटन दबाएं" else "1. Tap 'Enable in Settings' button"
            "guide_step_2" -> if (isHindi) "2. 'Installed Apps / Services' में 'AdSkip Pro' चुनें" else "2. Select 'AdSkip Pro' under Installed Services"
            "guide_step_3" -> if (isHindi) "3. स्विच को चालू (ON) करें और Allow दबाएं" else "3. Toggle switch ON and tap Allow"
            "guide_close" -> if (isHindi) "समझ गया" else "Got It"
            "github_card_title" -> if (isHindi) "गिटहब से ऐप डाउनलोड और अपडेट" else "Install & Update via GitHub"
            "github_card_desc" -> if (isHindi) "इस ऐप की APK अपने मोबाइल पर इंस्टॉल करने के लिए गिटहब रिलीज़ खोलें या गाइड देखें" else "Download and install the APK on your mobile directly from GitHub"
            "btn_download_github_apk" -> if (isHindi) "गिटहब से APK डाउनलोड करें" else "Download APK from GitHub"
            "btn_how_to_install_phone" -> if (isHindi) "मोबाइल में इंस्टॉल करने का तरीका" else "How to Install on Mobile"
            "install_guide_title" -> if (isHindi) "मोबाइल पर APK कैसे इंस्टॉल करें?" else "How to Install APK on Mobile?"
            "install_guide_step_1" -> if (isHindi) "1. ऊपर AI Studio के Settings मेन्यू से 'Push to GitHub' या 'Export APK' करें" else "1. From AI Studio Settings menu, select 'Push to GitHub' or 'Export APK'"
            "install_guide_step_2" -> if (isHindi) "2. अपने मोबाइल में APK फ़ाइल डाउनलोड करें" else "2. Download the generated APK file on your Android phone"
            "install_guide_step_3" -> if (isHindi) "3. APK फ़ाइल खोलें और 'Install' पर टैप करें (जरूरत पड़ने पर Allow Unknown Apps करें)" else "3. Open the APK and tap Install (enable 'Install unknown apps' if prompted)"
            "install_guide_step_4" -> if (isHindi) "4. ऐप ओपन करके Accessibility ऑन करें—सभी ऐड्स अपने आप स्किप होंगे!" else "4. Open AdSkip Pro, turn ON Accessibility, and enjoy ad-free viewing!"
            "vpn_blocker_title" -> if (isHindi) "مکمل اشتہار بلاکر (Zero Ads Mode)" else "Full Zero-Ads Blocker (DNS & VPN)"
            "vpn_blocker_desc" -> if (isHindi) "براؤزر، یوٹیوب اور تمام ایپس میں اشتہارات کو لوڈ ہونے سے پہلے ہی روکتا ہے تاکہ کوئی ایڈ شو ہی نہ ہو۔" else "Blocks ads from loading at the network level across browsers, YouTube & all apps"
            "vpn_active_status" -> if (isHindi) "مکمل ایڈ بلاکر فعال ہے (کوئی ایڈ شو نہیں ہوگی)" else "Zero-Ads Blocker Active (No Ads Will Show)"
            "vpn_inactive_status" -> if (isHindi) "اشتہار بلاکر بند ہے - آن کریں" else "Ad-Blocker Inactive - Tap to Activate"
            "btn_activate_vpn" -> if (isHindi) "مکمل اشتہار بلاکر آن کریں (Zero Ads)" else "Turn ON Zero-Ads Shield"
            "btn_deactivate_vpn" -> if (isHindi) "اشتہار بلاکر بند کریں" else "Turn OFF Zero-Ads Shield"
            "network_blocked_stat" -> if (isHindi) "براؤزر و ایپس کے بلاک شدہ اشتہارات" else "Network Ads Blocked"
            "recent_blocked_servers" -> if (isHindi) "روکے گئے ایڈ سرورز" else "Blocked Ad Servers"
            else -> key
        }
    }
}
